<?php
$titulo='Categorías';require_once 'header.php';
if($_SERVER['REQUEST_METHOD']==='POST'){try{validarCsrf();$id=(int)$_POST['id'];$nombre=trim($_POST['nombre']);if(!$nombre)throw new RuntimeException('Escribe un nombre.');if($id){$st=$conn->prepare("SELECT nombre FROM categorias WHERE id=?");$st->bind_param('i',$id);$st->execute();$antes=$st->get_result()->fetch_assoc();if(!$antes)throw new RuntimeException('Categoría no encontrada.');$st=$conn->prepare("UPDATE categorias SET nombre=? WHERE id=?");$st->bind_param('si',$nombre,$id);$st->execute();registrarHistorial($conn,'categorias','editar','Categoría actualizada',['categoria'=>$id,'nombre_anterior'=>$antes['nombre'],'nombre_nuevo'=>$nombre]);}else{$st=$conn->prepare("INSERT INTO categorias(nombre) VALUES(?)");$st->bind_param('s',$nombre);$st->execute();$id=$st->insert_id;registrarHistorial($conn,'categorias','crear','Categoría creada',['categoria'=>$id,'nombre'=>$nombre]);}flash('success','Categoría guardada.');}catch(Throwable $e){flash('error','No se pudo guardar la categoría: '.$e->getMessage());}redir('categorias.php');}
$cs=$conn->query("SELECT c.*,COUNT(p.id) productos FROM categorias c LEFT JOIN productos p ON p.categoria_id=c.id GROUP BY c.id ORDER BY c.nombre");
?>
<div class="toolbar"><div><h2>Categorías</h2><p>Organiza los productos sin alterar los existentes.</p></div></div>
<section class="panel"><form method="post" class="inline-form"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input name="nombre" placeholder="Nueva categoría" required><input type="hidden" name="id" value="0"><button class="btn primary">Crear categoría</button></form></section>
<section class="panel table-wrap"><table><thead><tr><th>Nombre</th><th>Productos</th><th>Estado</th></tr></thead><tbody><?php while($c=$cs->fetch_assoc()):?><tr><td><?=e($c['nombre'])?></td><td><?=e($c['productos'])?></td><td><?= $c['activa']?'Activa':'Inactiva'?></td></tr><?php endwhile;?></tbody></table></section>
